<script setup lang="ts">
import { ref, computed } from 'vue';
import type { Person, Interaction, Entity, PersonReflection, FollowUp } from '@zhijiao/shared';
import { partialDateSchema } from '@zhijiao/shared';
import { base, directory, entities } from '../state'; import { label, localDate } from '../format';
import Drawer from './Drawer.vue'; import PersonPicker from './PersonPicker.vue'; import Icon from './Icon.vue';
const props = defineProps<{ personId?: string; busy?: boolean; failure?: string }>(); const emit = defineEmits<{ save: [records: Entity[], remove: string[]]; close: [] }>();
const selected = ref<string[]>(props.personId ? [props.personId] : []); const drafts = ref<Person[]>([]); const picker = ref(false); const error = ref('');
const title = ref(''); const content = ref(''); const date = ref(localDate()); const exactTime = ref(''); const timezone = ref(Intl.DateTimeFormat().resolvedOptions().timeZone); const channel = ref(''); const location = ref(''); const eventKind = ref('');
interface ReflectionDraft { id: string; personId: string; mode: 'new' | 'existing'; existingId: string; type: PersonReflection['type']; content: string; relation: 'arose' | 'supports' | 'contradicts' | 'revises'; explanation: string }
const reflections = ref<ReflectionDraft[]>([]); const taskOpen = ref(false); const taskTitle = ref(''); const taskType = ref<FollowUp['type']>('promise'); const responsibility = ref<FollowUp['responsibility']>('me'); const dueDate = ref(''); const details = ref('');
const names = computed(() => selected.value.map(id => ({ id, name: directory.value.find(person => person.personId === id)?.displayName ?? drafts.value.find(person => person.id === id)?.displayName ?? '尚未同步人物' })));
const availableReflections = computed(() => entities.value.filter((entity): entity is PersonReflection => entity.kind === 'reflection' && selected.value.includes(entity.personId)));
function addReflection() { reflections.value.push({ id: crypto.randomUUID(), personId: selected.value.length === 1 ? selected.value[0] : '', mode: 'new', existingId: '', type: 'feeling', content: '', relation: 'arose', explanation: '' }); }
function choose(ids: string[], people: Person[]) { selected.value = ids; drafts.value = people; picker.value = false; }
function submit() {
 if (props.busy) return; error.value = '';
 if (!selected.value.length || !title.value.trim()) { error.value = '请选择参与人物并填写交往标题。'; return; }
 if (date.value && !partialDateSchema.safeParse(date.value).success || dueDate.value && !partialDateSchema.safeParse(dueDate.value).success) { error.value = '日期格式不正确，请保留已知精度。'; return; }
 if (exactTime.value) { try { new Intl.DateTimeFormat('zh-CN', { timeZone: timezone.value }); if (!Number.isFinite(new Date(exactTime.value).getTime())) throw Error(); } catch { error.value = '请填写合法的精确时间和 IANA 时区。'; return; } }
 const event: Interaction = { ...base(), kind: 'interaction', title: title.value.trim(), participantIds: [...selected.value], content: content.value.trim(), ...(date.value ? { occurredOn: date.value } : {}), ...(exactTime.value ? { occurredAt: new Date(exactTime.value).toISOString(), timezone: timezone.value } : {}), ...(channel.value.trim() ? { channel: channel.value.trim() } : {}), ...(location.value.trim() ? { location: location.value.trim() } : {}), ...(eventKind.value.trim() ? { kindOfInteraction: eventKind.value.trim() } : {}) };
 const records: Entity[] = [...drafts.value.filter(person => selected.value.includes(person.id)), event];
 for (const item of reflections.value) {
   if (!selected.value.includes(item.personId)) { error.value = '每条感受都需要明确针对一名参与人物。'; return; }
   let reflectionId = item.existingId;
   if (item.mode === 'new') { if (!item.content.trim()) { error.value = '请填写感受，或移除空的感受条目。'; return; } const reflection: PersonReflection = { ...base(), kind: 'reflection', personId: item.personId, type: item.type, content: item.content.trim(), recordedOn: localDate(), status: 'current' }; records.push(reflection); reflectionId = reflection.id; }
   else if (!availableReflections.value.some(reflection => reflection.id === reflectionId && reflection.personId === item.personId)) { error.value = '请选择此人物的已有感受或印象。'; return; }
   records.push({ ...base(), kind: 'reflectionLink', reflectionId, interactionId: event.id, relationType: item.relation, explanation: item.explanation.trim() || undefined });
 }
 if (taskOpen.value && taskTitle.value.trim()) records.push({ ...base(), kind: 'followUp', title: taskTitle.value.trim(), personIds: [...selected.value], type: taskType.value, responsibility: responsibility.value, sourceInteractionId: event.id, details: details.value.trim() || undefined, dueDate: dueDate.value || undefined, status: 'pending' });
 if (taskOpen.value && !taskTitle.value.trim()) { error.value = '请填写事项标题，或收起该事项。'; return; }
 emit('save', records, []);
}
</script>
<template><Drawer title="记一笔" subtitle="记住这次相处" :busy="busy" @close="emit('close')"><form id="journal-form" class="form-grid" @submit.prevent="submit"><p v-if="error || failure" class="error" role="alert">{{ error || failure }}</p><label class="field"><span>和谁在一起 *</span><button type="button" class="people-select" @click="picker = true"><Icon name="people" />{{ names.map(person => person.name).join('、') || '选择一位或多位人物' }}<Icon name="arrow" :size="16" /></button></label><label class="field"><span>这次交往 *</span><input v-model="title" required placeholder="给这次交往一个简短标题"></label><label class="field"><span>发生了什么</span><textarea v-model="content" rows="5" placeholder="聊到的事、相处的细节…" /></label><label class="field"><span>日期</span><input v-model="date" placeholder="YYYY-MM-DD，可保留已知精度"></label><details class="form-details"><summary>时间、渠道和地点</summary><div class="form-grid"><label class="field"><span>精确时间（可不填）</span><input v-model="exactTime" type="datetime-local"></label><label v-if="exactTime" class="field"><span>时区</span><input v-model="timezone"></label><label class="field"><span>交往类型</span><input v-model="eventKind" placeholder="见面、消息、通话…"></label><label class="field"><span>渠道</span><input v-model="channel"></label><label class="field"><span>地点</span><input v-model="location"></label></div></details><section class="form-section"><div class="section-title"><h3>我的感受与印象</h3><button type="button" class="text-button" @click="addReflection"><Icon name="plus" :size="16" />添加</button></div><p v-if="!reflections.length" class="muted">可选。记录当时的感受，或让这次交往支持、反驳已有印象。</p><div v-for="(item, index) in reflections" :key="item.id" class="nested-form"><label class="field"><span>针对谁 *</span><select v-model="item.personId" required><option value="">请选择具体人物</option><option v-for="person in names" :key="person.id" :value="person.id">{{ person.name }}</option></select></label><div class="segmented"><button type="button" :class="{ active: item.mode === 'new' }" @click="item.mode = 'new'">新感受</button><button type="button" :class="{ active: item.mode === 'existing' }" @click="item.mode = 'existing'">已有印象</button></div><template v-if="item.mode === 'new'"><label class="field"><span>类型</span><select v-model="item.type"><option v-for="type in ['feeling','hypothesis','experience']" :key="type" :value="type">{{ label(type) }}</option></select></label><label class="field"><span>我的想法 *</span><textarea v-model="item.content" rows="3" required placeholder="我感觉… / 我暂时觉得…" /></label></template><label v-else class="field"><span>关联的感受或印象 *</span><select v-model="item.existingId" required><option value="">选择已有印象</option><option v-for="reflection in availableReflections.filter(record => record.personId === item.personId)" :key="reflection.id" :value="reflection.id">{{ reflection.content.slice(0, 80) }}</option></select></label><label class="field"><span>这次交往对它的影响</span><select v-model="item.relation"><option v-for="relation in ['arose','supports','contradicts','revises']" :key="relation" :value="relation">{{ label(relation) }}</option></select></label><label class="field"><span>说明</span><textarea v-model="item.explanation" rows="2" /></label><button type="button" class="text-button danger" @click="reflections.splice(index, 1)">移除此条感受</button></div></section><section class="form-section"><div class="section-title"><h3>约定或计划</h3><button type="button" class="text-button" @click="taskOpen = !taskOpen">{{ taskOpen ? '收起' : '添加事项' }}</button></div><div v-if="taskOpen" class="form-grid"><label class="field"><span>事项标题 *</span><input v-model="taskTitle" required placeholder="接下来需要做什么"></label><label class="field"><span>类型</span><select v-model="taskType"><option value="promise">约定</option><option value="plan">个人计划</option></select></label><label class="field"><span>由谁负责</span><select v-model="responsibility"><option value="me">我</option><option value="other">对方</option><option value="joint">共同</option></select></label><label class="field"><span>期限日期（可不填）</span><input v-model="dueDate" placeholder="YYYY-MM-DD"></label><label class="field"><span>细节</span><textarea v-model="details" rows="2" /></label></div></section><p class="muted form-note">这次交往、感受与事项会一次保存，事件依据自动关联。</p></form><template #footer><button class="button secondary" :disabled="busy" @click="emit('close')">取消</button><button class="button primary" type="submit" form="journal-form" :disabled="busy">{{ busy ? '正在加密保存…' : '保存这一笔' }}</button></template></Drawer><PersonPicker v-if="picker" multiple :selected="selected" :initial-drafts="drafts" @confirm="choose" @cancel="picker = false" /></template>
